const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(c/100);
let state={requests:[],documents:[],visitors:[]},tab='Overview',draft=null;
const groups=[
 ['Home','home',[['Overview','Home']]],
 ['Booking Calendar','calendar',[['Calendar','Calendar'],['Requests & bookings','Booking List']]],
 ['Sales','sales',[['Orders','Orders'],['Design orders','Design Orders'],['Payments','All Payments'],['Sales reports','Sales Overview'],['Order process','Order Process']]],
 ['Catalog','catalog',[['Products','Products'],['Inventory','Inventory'],['Vehicle templates','Vehicle Templates'],['Template requests','Template Requests'],['Pricing & forms','Options & Pricing'],['Discount codes','Coupons']]],
 ['Site & Design','site',[['Web Design','Website Builder'],['Forms','Form Builder'],['Services','Services & Terms'],['Projects','Our Work']]],
 ['Getting Paid','paid',[['Pay Links','Pay Links'],['Invoices','Invoices'],['Quotes','Price Quotes'],['Business settings','Getting Paid Settings']]],
 ['Customers & Leads','customers',[['Customers','Contacts'],['Requests & bookings','Forms & Submissions']]],
 ['Analytics','analytics',[['Analytics','Highlights'],['Real-time','Real-time'],['Sales reports','Sales Reports']]],
 ['Settings','settings',[['Business settings','Business Info'],['Connections','Integrations']]]];
const tabs=[...new Set(groups.flatMap(g=>g[2].map(t=>t[0])))];
const labels=Object.fromEntries(groups.flatMap(g=>g[2]));labels['Requests & bookings']='Booking List';labels['Overview']='Home';
const descriptions={Overview:'Manage your business, customers and website in one place.',Invoices:'Create invoices, request a deposit and track the remaining balance.',Quotes:'Create price quotes and convert accepted quotes into invoices.',Products:'Manage your catalog, availability, design options and pricing.',Inventory:'Track stock and availability across your products.',Customers:'Manage contacts and import your customer directory.',Analytics:'See activity and payments recorded on your new website.',Payments:'Track payments received against your invoices.',Calendar:'Review requested appointments in Toronto time.',Connections:'Manage the services your business needs.'};
let openGroup='Home',renderId=0;
function nav(){const group=groups.find(g=>g[0]===openGroup);$('#breadcrumb').textContent=group?.[0]||'Satin Graphic';$('#nav').innerHTML=groups.map(([name,icon,children])=>name==='Home'?`<button class="nav-main ${tab==='Overview'?'active':''}" data-tab="Overview">${glyph(icon)}<span>Home</span></button>`:`<div class="nav-group"><button class="nav-main ${openGroup===name?'expanded':''}" data-group="${name}" aria-label="${name}" aria-expanded="${openGroup===name}">${glyph(icon)}<span>${name}</span><span class="chevron" aria-hidden="true">${openGroup===name?'⌃':'›'}</span></button><div class="nav-children" ${openGroup===name?'':'hidden'}>${children.map(([key,label])=>`<button class="${tab===key?'active':''}" data-tab="${key}" ${tab===key?'aria-current="page"':''}>${label}</button>`).join('')}</div></div>`).join('');}
function glyph(name){const paths={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16',sales:'M12 3v18m5-14c-2-4-10-4-10 1s10 3 10 7-8 5-10 1',catalog:'m12 3 9 5v10l-9 5-9-5V8zM3 8l9 5 9-5m-9 5v10',site:'M3 4h18v14H3zM8 22h8m-4-4v4',paid:'M7 3H3v18h18V7M7 7h10m-5-4v12m-4-4 4 4 4-4',customers:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8m-7 9v-3c0-5 14-5 14 0v3m0-17a4 4 0 0 1 0 8m3 3c3 1 3 3 3 6',analytics:'M3 3v18h18M6 16l5-6 4 3 6-8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="${paths[name]}"/></svg>`;}
function go(key){tab=key;openGroup=groups.find(g=>g[0]===openGroup&&g[2].some(t=>t[0]===key))?.[0]||groups.find(g=>g[2].some(t=>t[0]===key))?.[0]||'Home';history.replaceState(null,'','#'+encodeURIComponent(key));render();message('');document.body.classList.remove('nav-open');$('#sidebar-toggle').setAttribute('aria-expanded','false');}
const initial=decodeURIComponent(location.hash.slice(1));if(tabs.includes(initial)){tab=initial;openGroup=groups.find(g=>g[2].some(t=>t[0]===tab))[0];}
async function api(path,data){const r=await fetch('/api/admin/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Operation failed');return v;}
function message(s,error=false){$('#message').textContent=s;$('#message').className=error?'status-error':'';}
async function load(){try{state=await api('overview');render();message('');}catch(e){message(e.message,true);$('#content').innerHTML='<div class="panel"><h2>Management unavailable</h2><p>Sign in with the site owner’s account to access customer information.</p><a class="button" target="_top" href="/signin-with-chatgpt?return_to=/admin/">Owner sign-in</a></div>';}}
$('#refresh').onclick=load;
function render(){const previous=$('#content');const cleanRoot=previous.cloneNode(false);cleanRoot.className='';previous.replaceWith(cleanRoot);const ticket=++renderId;document.title=(labels[tab]||tab)+' · Satin Graphic';$('#title').textContent=labels[tab]||tab;$('#page-description').textContent=descriptions[tab]||'';nav();$('#content').innerHTML='<p class="empty">Loading…</p>';$('#content').onclick=null;
 if(tab==='Services'||tab==='Projects'){const chosen=tab;import('/admin/services.mjs').then(m=>{if(renderId===ticket)return (chosen==='Services'?m.mountSettings:m.mountProjects)($('#content'),message);}).catch(e=>message(e.message,true));}else if(tab==='Overview')overview();else if(tab==='Requests & bookings'||tab==='Template requests')requests();else if(['Customers','Invoices','Quotes'].includes(tab)){const chosen=tab;import('/admin/commerce.mjs').then(m=>{if(renderId!==ticket)return;return (chosen==='Customers'?m.mountCustomers($('#content'),message):m.mountInvoices($('#content'),message,chosen==='Quotes'?'quotes':'invoices'));}).catch(e=>message(e.message,true));}
 else if(['Products','Inventory','Vehicle templates'].includes(tab)){const chosen=tab;import('/admin/products.mjs').then(m=>{if(renderId!==ticket)return;return (chosen==='Vehicle templates'?m.mountTemplates:m.mountProducts)($('#content'),message,chosen==='Inventory');}).catch(e=>message(e.message,true));}
 else if(tab==='Orders')documents();else if(['Pricing & forms','Discount codes','Order process','Design orders'].includes(tab)){const chosen=tab;import('/studio/admin.mjs').then(m=>{if(renderId!==ticket)return;if(chosen==='Pricing & forms')return m.mountRuleBuilder($('#content'),message,window.satinPricingPath);if(chosen==='Discount codes')return m.mountCoupons($('#content'),message);if(chosen==='Order process')return m.mountProcess($('#content'),message);return m.mountDesignOrders($('#content'),message);}).catch(e=>message(e.message,true));}
 else if(tab==='Web Design')import('/admin/builder.mjs').then(m=>{if(renderId===ticket)return m.mount($('#content'),message);}).catch(e=>message(e.message,true));else if(tab==='Forms')editor();else if(tab==='Connections')connections();else import('/admin/reports.mjs').then(m=>{if(renderId===ticket)return m.mount($('#content'),message,tab,state);}).catch(e=>message(e.message,true));}
$('#nav').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.group){openGroup=openGroup===b.dataset.group?'':b.dataset.group;nav();}if(b.dataset.tab)go(b.dataset.tab);};
$('#sidebar-toggle').onclick=()=>{$('#sidebar-toggle').setAttribute('aria-expanded',String(document.body.classList.toggle('nav-open')));};
$('#quick-actions').onclick=()=>{$('#quick-menu').hidden=!$('#quick-menu').hidden;};
$('#quick-menu').onclick=e=>{const b=e.target.closest('[data-quick]');if(!b)return;$('#quick-menu').hidden=true;go(b.dataset.quick);const selector={Invoices:'[data-new-invoice]',Quotes:'[data-new-invoice]',Customers:'[data-new-customer]',Products:'[data-new-product]'}[b.dataset.quick];const observer=new MutationObserver(()=>{const el=$(selector);if(el){observer.disconnect();el.click();}});observer.observe($('#content'),{childList:true,subtree:true});setTimeout(()=>observer.disconnect(),10000);};
$('#dashboard-search').oninput=e=>{const q=e.target.value.trim().toLowerCase(),root=$('#search-results');root.hidden=!q;root.innerHTML=tabs.filter(t=>(labels[t]+' '+t).toLowerCase().includes(q)).map(t=>`<button data-result="${t}">${labels[t]||t}</button>`).join('')||'<p>No matching pages</p>';};
$('#search-results').onclick=e=>{const b=e.target.closest('[data-result]');if(b){go(b.dataset.result);$('#search-results').hidden=true;$('#dashboard-search').value='';}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#search-results').hidden=true;$('#quick-menu').hidden=true;document.body.classList.remove('nav-open');}});
function overview(){import('/admin/reports.mjs').then(m=>{if(tab==='Overview')return m.mount($('#content'),message,'Overview',state);}).catch(e=>message(e.message,true));}
function requests(){const templateOnly=tab==='Template requests',source=templateOnly?state.requests.filter(r=>r.service==='Vehicle template request'):state.requests;let rows=source;$('#content').innerHTML=`<div class="panel"><div class="toolbar"><h2>Service requests & appointment requests</h2><button id="export">Export CSV</button></div><label>Filter status<select id="filter"><option value="">All requests</option>${['pending_confirmation','confirmed','completed','cancelled'].map(s=>`<option>${s}</option>`).join('')}</select></label><div id="request-table"></div></div>`;const draw=()=>{$('#request-table').innerHTML=rows.length?`<div class="scroll"><table><thead><tr><th>Customer</th><th>Service / requested time</th><th>Details</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b><br>${esc(r.email)}<br>${esc(r.phone)}<br><span class="muted">SG-${esc(r.id.slice(0,8).toUpperCase())}</span></td><td>${esc(r.service)}<br>${esc(r.type)}<br>${esc(r.preferred_date)} ${esc(r.preferred_time)}<br><span class="muted">Toronto time</span></td><td class="details">${requestDetailsHTML(r.details)}</td><td><select data-status="${r.id}">${['pending_confirmation','confirmed','completed','cancelled'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No matching requests.</p>';};draw();$('#filter').onchange=e=>{rows=source.filter(r=>!e.target.value||r.status===e.target.value);draw();};$('#request-table').onchange=async e=>{if(!e.target.dataset.status)return;const r=state.requests.find(r=>r.id===e.target.dataset.status),old=r.status;try{e.target.disabled=true;await api('request',{id:r.id,status:e.target.value});r.status=e.target.value;message('Request status saved.');}catch(err){e.target.value=old;message(err.message,true);}finally{e.target.disabled=false;}};$('#export').onclick=()=>{const all=[['Reference','Name','Email','Phone','Service','Type','Date','Time','Status','Details'],...rows.map(r=>['SG-'+r.id.slice(0,8),r.name,r.email,r.phone,r.service,r.type,r.preferred_date,r.preferred_time,r.status,formatDetails(r.details)])];download('satin-requests.csv',all.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv');};}
function requestDetailsHTML(raw){try{const d=JSON.parse(raw);if(d.attachments?.length)return '<p>'+esc(formatDetails(raw))+'</p>'+d.attachments.map(f=>`<a href="/api/studio/file?id=${esc(f.id)}" target="_blank" rel="noopener">Download ${esc(f.name)}</a>`).join('<br>');if(Array.isArray(d.items)&&d.paymentStatus){return `<p><b>Print checkout · ${esc(d.paymentStatus)}</b><br>${esc(d.preflightStatus)}<br>${esc(d.shipping?.label)} · CAD $${Number(d.shipping?.amount||0).toFixed(2)} before tax</p><p>${esc([d.address?.street1,d.address?.street2,d.address?.city,d.address?.state,d.address?.zip].filter(Boolean).join(', '))}</p>${d.items.map(i=>`<div style="margin:12px 0;padding:12px;border:1px solid #dce3ed;border-radius:8px"><b>${esc(i.jobName||i.name)}</b><br>${esc(i.values?.quantity)} · ${esc(i.spec?.width)} × ${esc(i.spec?.height)} in · ${esc(i.spec?.sides)} side(s)<br>CAD $${(Number(i.price?.net||0)/100).toFixed(2)} before tax<br>${i.designRequested?'Designer requested':'Customer confirmed files: '+(i.proof?'Yes':'No')}<br>${(i.reports||[]).map(f=>`<a href="/api/studio/file?id=${esc(f.id)}" target="_blank" rel="noopener">${esc(f.name)}</a> · ${esc(f.status)}<br>`).join('')}</div>`).join('')}`;}}catch{}return esc(formatDetails(raw));}
+function formatDetails(raw){try{const d=JSON.parse(raw);return [d.services?.join(', '),d.vehicle,d.plan,d.notes,d.estimate,d.contactPreference,d.items?.map(i=>(i.jobName||i.name)+' · '+i.values?.quantity+' · '+i.reports?.map(r=>r.name+' ['+r.status+']').join(', ')).join('\n'),d.paymentStatus,d.preflightStatus,d.shipping?.label,...Object.entries(d.custom||{}).map(([k,v])=>k+': '+v)].filter(Boolean).join('\n');}catch{return raw;}}
function download(name,value,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([value],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function documents(){const kind={Quotes:'quote',Invoices:'invoice',Orders:'order'}[tab];const rows=state.documents.filter(d=>d.kind===kind);$('#content').innerHTML=`<div class="toolbar"><button class="primary" id="new-doc">New ${kind}</button><span class="muted">CAD · internal records · no payment or email is sent</span></div><div class="panel">${rows.length?`<div class="scroll"><table><thead><tr><th>Reference / customer</th><th>Total</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${rows.map(d=>`<tr><td>SG-${esc(d.id.slice(0,8).toUpperCase())}<br><b>${esc(d.data.customer)}</b><br>${esc(d.data.email)}</td><td>${money(d.data.total)}</td><td>${esc(d.status)}</td><td>${esc(new Date(d.updated_at).toLocaleDateString())}</td><td><button data-doc="${d.id}">Open</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No saved '+kind+'s yet.</p>'}</div><div id="doc-editor"></div>`;$('#new-doc').onclick=()=>documentForm(kind);$('#content').querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>documentForm(kind,state.documents.find(d=>d.id===b.dataset.doc)));}
function documentForm(kind,record){const d=record?.data||{customer:'',email:'',tax:13,notes:'',items:[{description:'',quantity:1,price:0}]};$('#doc-editor').innerHTML=`<form id="document" class="panel"><div class="document-heading"><b>Satin Graphic</b><p class="muted">50 Viceroy Rd, Unit 22–23 · Vaughan, ON · info@satingraphic.ca</p></div><h2>${record?'Edit':'New'} ${kind}</h2><div class="form-grid"><label>Customer<input name="customer" required maxlength="120" value="${esc(d.customer)}"></label><label>Email<input name="email" type="email" value="${esc(d.email)}"></label><label>Status<select name="status">${['draft','sent','accepted','cancelled'].map(s=>`<option ${record?.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Tax % · confirm for this sale<input name="tax" type="number" min="0" max="30" step=".01" value="${d.tax}"></label></div><p class="muted">Description · quantity · unit price CAD</p><div id="lines"></div><div class="toolbar no-print"><button type="button" id="add-line">Add item</button></div><label>Notes<textarea name="notes" maxlength="2000">${esc(d.notes)}</textarea></label><h3 id="doc-total"></h3><div class="toolbar no-print"><button class="primary">Save ${kind}</button><button type="button" id="print">Print / Save PDF</button></div></form>`;let items=structuredClone(d.items);function lines(){$('#lines').innerHTML=items.map((i,n)=>`<div class="line"><input aria-label="Item description" data-i="${n}" data-k="description" required value="${esc(i.description)}"><input aria-label="Quantity" data-i="${n}" data-k="quantity" type="number" min=".01" step=".01" required value="${i.quantity}"><input aria-label="Unit price" data-i="${n}" data-k="price" type="number" min="0" step=".01" required value="${i.price}"><button type="button" aria-label="Remove item" data-remove="${n}">×</button></div>`).join('');total();}function total(){const subtotal=Math.round(items.reduce((s,i)=>s+Number(i.quantity)*Number(i.price),0)*100);$('#doc-total').textContent='Subtotal '+money(subtotal)+' · Total '+money(subtotal+Math.round(subtotal*Number($('#document').elements.tax.value)/100));}lines();$('#lines').oninput=e=>{if(e.target.dataset.k){items[Number(e.target.dataset.i)][e.target.dataset.k]=e.target.dataset.k==='description'?e.target.value:Number(e.target.value);total();}};$('#lines').onclick=e=>{if(e.target.dataset.remove!==undefined&&items.length>1){items.splice(Number(e.target.dataset.remove),1);lines();}};$('#add-line').onclick=()=>{items.push({description:'',quantity:1,price:0});lines();};$('#document').elements.tax.oninput=total;$('#print').onclick=()=>{document.body.classList.add('print-document');window.print();};window.onafterprint=()=>document.body.classList.remove('print-document');$('#document').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),b=e.target.querySelector('[type=submit]')||e.target.querySelector('.primary');b.disabled=true;try{await api('document',{id:record?.id,kind,status:fd.get('status'),customer:fd.get('customer'),email:fd.get('email'),notes:fd.get('notes'),tax:Number(fd.get('tax')),items});await load();message('Document saved.');}catch(err){message(err.message,true);b.disabled=false;}};$('#doc-editor').scrollIntoView({behavior:'smooth'});}
function connections(){$('#content').innerHTML=`<div class="panel"><h2>Checkout, accounts & delivery</h2><p class="muted">These services are not connected. Checkout and customer sign-in remain unavailable until credentials, provider approval and end-to-end tests are complete.</p><div class="scroll"><table><thead><tr><th>Service</th><th>Use</th><th>Required setup</th></tr></thead><tbody>${[['Stripe','Visa / Mastercard checkout','Business account, server key, signed webhook, product prices and refund flow','https://docs.stripe.com/payments/checkout'],['Escrow.com','Hold and release payment under agreed terms','Account approval, transaction eligibility, fees, inspection and release terms','https://www.escrow.com/api/docs'],['Google / Apple / Facebook','Customer sign-in','Registered apps, verified domains, callback URLs, account linking and recovery',''],['UPS','Rates, labels and tracking','Shipper account, OAuth credentials, package sizes / weights and pickup address','https://developer.ups.com/get-started'],['FedEx','Rates, labels and tracking','Shipping account, OAuth credentials and production approval','https://developer.fedex.com/']].map(([n,u,r,link])=>`<tr><td><b>${n}</b><br><span class="pill">Not connected</span></td><td>${u}</td><td>${r}${link?`<br><a href="${link}" target="_blank" rel="noopener">Provider setup</a>`:''}</td></tr>`).join('')}</tbody></table></div><p class="notice">Owner access currently uses ChatGPT sign-in. External customer accounts are a separate integration. Never paste provider secret keys into a public form.</p></div>`;}
function editor(){
 $('#content').innerHTML=`<div class="toolbar"><label>Page path<input id="page-path" value="/satin" placeholder="/satin/auto-detailing"></label><button id="open-page">Open page</button><button id="device">Mobile preview</button><button id="edit-pricing-form">Edit pricing form</button><button id="save-draft">Save draft</button><button class="primary" id="publish">Publish changes</button></div><p class="muted">Edit headings, paragraphs and image paths; drag sections or use Move up / down. Custom fields currently apply to the working service request and booking forms. Use Edit pricing form to change fields, options, calculation, deposit and discount on this page.</p><div class="editor"><div class="editor-controls panel"><div id="edit-controls">Open a page to start.</div></div><div><iframe class="preview" id="preview" title="Website preview"></iframe></div></div>`;
 let page='',doc=null,elements=[],sections=[];
 $('#edit-pricing-form').onclick=()=>{window.satinPricingPath=$('#page-path').value.replace(/\/$/,'');tab='Pricing & forms';render();};
 $('#device').onclick=()=>{const mobile=$('#preview').classList.toggle('mobile');$('#device').textContent=mobile?'Desktop preview':'Mobile preview';};
 $('#open-page').onclick=async()=>{const value=$('#page-path').value.replace(/\/$/,'');if(!/^\/satin(?:\/[a-z0-9-]+)*$/.test(value)){message('Use a valid /satin page path.',true);return;}page=value;message('Loading page and saved draft…');try{draft=await api('content?path='+encodeURIComponent(page));$('#preview').src=page+'/?cms=1';}catch(e){message(e.message,true);}};
 $('#preview').onload=()=>{const win=$('#preview').contentWindow;const ready=()=>{try{doc=$('#preview').contentDocument;const parent=doc.querySelector('#main>.page-enter');if(!parent){message('This page cannot be edited.',true);return;}elements=[...doc.querySelectorAll('#main h1,#main h2,#main h3,#main p,#main img')].map(el=>({el,selector:selector(el),type:el.tagName==='IMG'?'image':'text',original:el.tagName==='IMG'?new URL(el.src).pathname:el.textContent}));sections=[...parent.children].map((el,index)=>({el,index,title:el.querySelector('h1,h2,h3')?.textContent||el.tagName+' '+(index+1)}));for(const edit of draft.edits||[]){const item=elements.find(i=>i.selector===edit.selector);if(item){if(edit.type==='text')item.el.textContent=edit.value;else{item.el.removeAttribute('srcset');item.el.closest('picture')?.querySelectorAll('source').forEach(s=>s.remove());item.el.src=edit.value;}}}if(draft.order?.length===sections.length&&draft.order.every(i=>sections[i])){sections=draft.order.map(i=>sections[i]);sections.forEach(s=>parent.append(s.el));}draw();message('Draft ready. Changes stay private until Publish changes.');}catch(e){message('Could not load the editor preview.',true);}};if(win.__satinReady)ready();else win.addEventListener('satin-page-rendered',ready,{once:true});};
 function selector(el){if(el.id==='main')return '#main';const p=el.parentElement;if(!p)return '';const tag=el.tagName.toLowerCase(),siblings=[...p.children].filter(s=>s.tagName===el.tagName);return selector(p)+' > '+tag+':nth-of-type('+(siblings.indexOf(el)+1)+')';}
 function recordEdit(item,value){const i=draft.edits.findIndex(e=>e.selector===item.selector);const edit={selector:item.selector,type:item.type,value};if(i<0)draft.edits.push(edit);else draft.edits[i]=edit;if(item.type==='text')item.el.textContent=value;else if(/^\/satin\/img\/[a-zA-Z0-9_.-]+$/.test(value)){item.el.removeAttribute('srcset');item.el.closest('picture')?.querySelectorAll('source').forEach(s=>s.remove());item.el.src=value;}}
 function move(from,to){if(to<0||to>=sections.length)return;const [s]=sections.splice(from,1);sections.splice(to,0,s);const parent=doc.querySelector('#main>.page-enter');sections.forEach(s=>parent.append(s.el));draft.order=sections.map(s=>s.index);draw();}
 function draw(){const controls=$('#edit-controls');if(tab==='Forms'){controls.innerHTML='<h2>Form fields</h2><p class="muted">Existing contact and consent fields are preserved. Add extra fields below.</p><div id="fields"></div><button id="new-field">Add field</button>';drawFields();previewFields();$('#new-field').onclick=()=>{draft.fields.push({key:'field_'+crypto.randomUUID().slice(0,8),label:'New field',type:'text',required:false});drawFields();previewFields();};return;}
 controls.innerHTML=`<h2>Sections</h2><div id="section-list">${sections.map((s,i)=>`<div class="section-item" draggable="true" data-section="${i}"><b>${esc(s.title)}</b><div><button data-up="${i}" ${i===0?'disabled':''}>Move up</button> <button data-down="${i}" ${i===sections.length-1?'disabled':''}>Move down</button></div></div>`).join('')}</div><h2>Text & images</h2>${elements.map((item,i)=>`<label class="edit-row"><span>${item.type==='image'?'Image path':item.el.tagName}</span>${item.type==='image'?`<input data-edit="${i}" value="${esc(new URL(item.el.src).pathname)}">`:`<textarea data-edit="${i}" rows="3">${esc(item.el.textContent)}</textarea>`}</label>`).join('')}`;
 controls.oninput=e=>{if(e.target.dataset.edit!==undefined)recordEdit(elements[Number(e.target.dataset.edit)],e.target.value);};controls.onclick=e=>{if(e.target.dataset.up!==undefined)move(Number(e.target.dataset.up),Number(e.target.dataset.up)-1);if(e.target.dataset.down!==undefined)move(Number(e.target.dataset.down),Number(e.target.dataset.down)+1);};let dragging=null;$('#section-list').ondragstart=e=>{dragging=Number(e.target.closest('[data-section]').dataset.section);e.dataTransfer.effectAllowed='move';};$('#section-list').ondragover=e=>e.preventDefault();$('#section-list').ondrop=e=>{e.preventDefault();const target=e.target.closest('[data-section]');if(target&&dragging!==null)move(dragging,Number(target.dataset.section));dragging=null;};}
 function drawFields(){$('#fields').innerHTML=draft.fields.map((f,i)=>`<div class="edit-row"><label>Label<input data-field="${i}" data-prop="label" value="${esc(f.label)}" maxlength="120"></label><label>Type<select data-field="${i}" data-prop="type">${['text','email','number','textarea'].map(t=>`<option ${f.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="check"><input type="checkbox" data-field="${i}" data-prop="required" ${f.required?'checked':''}>Required</label><button data-remove-field="${i}">Remove field</button></div>`).join('');$('#fields').oninput=e=>{if(e.target.dataset.field!==undefined){draft.fields[Number(e.target.dataset.field)][e.target.dataset.prop]=e.target.type==='checkbox'?e.target.checked:e.target.value;previewFields();}};$('#fields').onclick=e=>{if(e.target.dataset.removeField!==undefined){draft.fields.splice(Number(e.target.dataset.removeField),1);drawFields();previewFields();}};}
 function previewFields(){const win=$('#preview').contentWindow;win.satinApplyContent?.({edits:[],order:[],fields:draft.fields});}
 async function save(publish){if(!doc||!page){message('Open a page first.',true);return;}const button=$(publish?'#publish':'#save-draft');button.disabled=true;try{await api('content',{path:page,edits:draft.edits,order:sections.map(s=>s.index),fields:draft.fields,publish});message(publish?'Changes published to this page.':'Draft saved. The public website is unchanged.');}catch(e){message(e.message,true);}finally{button.disabled=false;}}
 $('#save-draft').onclick=()=>save(false);$('#publish').onclick=()=>save(true);$('#open-page').click();
}
load();

async function pricing(){
 $('#content').innerHTML='<p>Loading current pricing…</p>';try{const p=await api('pricing');if(tab!=='Pricing')return;$('#content').innerHTML=`<form id="pricing" class="panel"><h2>Wrap estimator prices</h2><p class="muted">Base prices in CAD, before tax. Vehicle size, coverage, material and finish multipliers still apply. These defaults came from the existing website; verify them before selling.</p><div class="form-grid">${Object.entries(p.bases).map(([k,v])=>`<label>${esc(k.replaceAll('-',' '))}<input name="${k}" type="number" min="0" max="1000000" step=".01" required value="${v}"></label>`).join('')}<label>Roof price multiplier<input name="roofMultiplier" type="number" min="1" max="3" step=".01" required value="${p.roofMultiplier}"></label><label>Design deposit CAD<input name="designDeposit" type="number" min="0" max="10000" step=".01" required value="${p.designDeposit}"></label></div><p class="muted">Saving publishes estimator prices immediately. Existing saved quotes and invoices keep their amounts.</p><button class="primary">Save prices</button></form>`;$('#pricing').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await api('pricing',{bases:Object.fromEntries(Object.keys(p.bases).map(k=>[k,Number(fd.get(k))])),roofMultiplier:Number(fd.get('roofMultiplier')),designDeposit:Number(fd.get('designDeposit'))});message('Estimator prices saved.');}catch(err){message(err.message,true);}finally{b.disabled=false;}};}catch(e){message(e.message,true);}
}
